import{_ as t,o as d,c as o,a0 as a}from"./chunks/framework.Obqu-B4P.js";const p=JSON.parse('{"title":"Config — cuora.toml","description":"","frontmatter":{},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md"}'),c={name:"reference/config.md"};function r(i,e,n,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="config-—-cuora-toml" tabindex="-1">Config — <code>cuora.toml</code> <a class="header-anchor" href="#config-—-cuora-toml" aria-label="Permalink to &quot;Config — `cuora.toml`&quot;">​</a></h1><h2 id="top-level" tabindex="-1">Top level <a class="header-anchor" href="#top-level" aria-label="Permalink to &quot;Top level&quot;">​</a></h2><table tabindex="0"><thead><tr><th>field</th><th>type</th><th>required</th><th>notes</th></tr></thead><tbody><tr><td><code>vaults</code></td><td><code>{name: vault}</code></td><td>optional</td><td>Named vault backends. <code>local</code> always exists implicitly (age, default paths); an entry only overrides it or adds more.</td></tr><tr><td><code>envs</code></td><td>`{env: vault</td><td>{vault}}`</td><td>optional</td></tr><tr><td><code>secrets</code></td><td><code>{VAR: cuora://ref}</code></td><td>optional</td><td>The declared secret surface: env-var name → <code>cuora://</code> ref. Bounds what <code>run</code>/<code>env</code> may inject — least privilege, no ambient vault dump.</td></tr><tr><td><code>deploy</code></td><td><code>{name: target}</code></td><td>optional</td><td>Named deploy targets — write-only sinks (<code>cuora deploy</code> pushes a stored value in; nothing ever reads one back).</td></tr><tr><td><code>guardrails</code></td><td><code>table</code></td><td>optional</td><td>Advisory op guardrails — accident prevention for standalone use, honestly <em>not</em> a policy boundary (a locally claimed actor is spoofable by construction).</td></tr><tr><td><code>serve</code></td><td><code>table</code></td><td>optional</td><td>The <code>cuora serve</code> surface — ndjson request/response on stdio plus the optional policy decision point. Absent, serve runs with no PDP — same advisory posture as the single-shot CLI.</td></tr><tr><td><code>identity</code></td><td><code>IdentityConfig</code></td><td>optional</td><td>Which backend holds the age identity — <code>[identity]</code>. Absent → <code>keyring</code> (fail closed; <code>auto</code>/<code>file</code> opt out).</td></tr></tbody></table><h2 id="vaults-name-—-a-named-vault-backend" tabindex="-1"><code>[vaults.NAME]</code> — a named vault backend <a class="header-anchor" href="#vaults-name-—-a-named-vault-backend" aria-label="Permalink to &quot;`[vaults.NAME]` — a named vault backend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>field</th><th>type</th><th>required</th><th>notes</th></tr></thead><tbody><tr><td><code>kind</code></td><td><code>string</code></td><td>optional</td><td>Backend kind — <code>&quot;age&quot;</code> (built-in, local file) or <code>&quot;cf&quot;</code> (self-hosted Cloudflare Worker + D1, <code>cuora-vault-cf</code>).</td></tr><tr><td><code>path</code></td><td><code>string</code></td><td>optional</td><td>Vault file path override (age impl; <code>~</code> is <em>not</em> expanded — write the path in full).</td></tr><tr><td><code>identity</code></td><td><code>string</code></td><td>optional</td><td>Age identity file override (<code>CUORA_IDENTITY_FILE</code> wins over this; see <code>cuora-ops</code>). <code>cf</code> vaults decrypt with the same keyfile — all vault impls store age ciphertext (ADR-0001).</td></tr><tr><td><code>recipients</code></td><td><code>list</code></td><td>optional</td><td>Extra age recipients to encrypt to, beyond the identity&#39;s public key (<code>age1…</code> strings).</td></tr><tr><td><code>url</code></td><td><code>string</code></td><td>optional</td><td>Worker base URL (<code>cf</code> impl), e.g. <code>https://cuora-vault.you.workers.dev</code>.</td></tr><tr><td><code>token_env</code></td><td><code>string</code></td><td>optional</td><td>Name of the env var holding the bearer token (<code>cf</code> impl) — the token <em>name</em> lives in config, the token <em>value</em> only in the process env.</td></tr><tr><td><code>tokens</code></td><td><code>BTreeMap&lt;Env, Ref&gt;</code></td><td>optional</td><td>Per-env scoped credentials (<code>cf</code> impl, P-003): env → the <code>cuora://</code> ref of a token stored in the <code>local</code> vault. Each resolved token authenticates as <code>CuoraHmac &amp;lt;ref-path&amp;gt;, ts, nonce, sig</code> — the ref path is the wire <code>token_id</code>. Token <em>refs</em> live in config, never token values.</td></tr><tr><td><code>private_refs</code></td><td><code>bool</code></td><td>optional</td><td>Opt-in private ref metadata (<code>cf</code> impl, P-004): storage keys become HMAC-derived hex and every record carries an age-encrypted <code>name</code> blob, so the remote store can&#39;t see which secrets exist. Default false; <code>cuora migrate --private-refs</code> rewrites existing rows.</td></tr><tr><td><code>cache</code></td><td><code>CacheScope</code></td><td>optional</td><td>Read-through encrypted local cache in front of this vault (P-007): <code>true</code> caches every env; a name or list scopes it — <code>cache = &quot;dev&quot;</code> or <code>cache = [&quot;dev&quot;, &quot;staging&quot;]</code>. Rows land at <code>$XDG_CACHE_HOME/cuora/&amp;lt;name&amp;gt;.age</code> as ordinary age ciphertext carrying the remote <code>version</code>/<code>rotated_at</code> verbatim; freshness is TTL-bounded (<code>cache_ttl_secs</code>) and writes are always remote-first. Meant for remote backends — <code>dev</code> may cache, <code>prod</code> should live-fetch.</td></tr><tr><td><code>cache_ttl_secs</code></td><td><code>int</code></td><td>optional</td><td>Cache freshness window in seconds — a cached row or env listing younger than this answers without a remote round-trip; past it the remote is re-fetched and the cache updated. A remote <em>failure</em> falls back to the stale copy — the offline mode. Absent → 300.</td></tr></tbody></table><h2 id="envs-—-env-→-vault-routing-table-form" tabindex="-1"><code>[envs]</code> — env → vault routing (table form) <a class="header-anchor" href="#envs-—-env-→-vault-routing-table-form" aria-label="Permalink to &quot;`[envs]` — env → vault routing (table form)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>field</th><th>type</th><th>required</th><th>notes</th></tr></thead><tbody><tr><td><code>vault</code></td><td><code>string</code></td><td>required</td><td>Vault name in <code>[vaults]</code> (or the implicit <code>local</code>).</td></tr></tbody></table><h2 id="deploy-name-—-a-write-only-push-target" tabindex="-1"><code>[deploy.NAME]</code> — a write-only push target <a class="header-anchor" href="#deploy-name-—-a-write-only-push-target" aria-label="Permalink to &quot;`[deploy.NAME]` — a write-only push target&quot;">​</a></h2><table tabindex="0"><thead><tr><th>field</th><th>type</th><th>required</th><th>notes</th></tr></thead><tbody><tr><td><code>kind</code></td><td><code>string</code></td><td>optional</td><td>Target kind — <code>&quot;cf-secrets-store&quot;</code> (Cloudflare account Secrets Store, <code>cuora-deploy-cf</code>).</td></tr><tr><td><code>account_id</code></td><td><code>string</code></td><td>optional</td><td>Cloudflare account id (<code>cf-secrets-store</code>).</td></tr><tr><td><code>store_id</code></td><td><code>string</code></td><td>optional</td><td>Secrets Store id (<code>cf-secrets-store</code>).</td></tr><tr><td><code>token_env</code></td><td><code>string</code></td><td>optional</td><td>Name of the env var holding the API token — never the token itself (<code>cf-secrets-store</code> defaults to <code>CLOUDFLARE_API_TOKEN</code>).</td></tr><tr><td><code>base_url</code></td><td><code>string</code></td><td>optional</td><td>API base URL override — for tests, gateways, and self-hosted proxies. Defaults to <code>https://api.cloudflare.com/client/v4</code>.</td></tr></tbody></table><h2 id="guardrails-—-advisory-op-table" tabindex="-1"><code>[guardrails]</code> — advisory op table <a class="header-anchor" href="#guardrails-—-advisory-op-table" aria-label="Permalink to &quot;`[guardrails]` — advisory op table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>field</th><th>type</th><th>required</th><th>notes</th></tr></thead><tbody><tr><td><code>default</code></td><td>`&quot;allow&quot;</td><td>&quot;deny&quot;`</td><td>optional</td></tr><tr><td><code>allow</code></td><td><code>op list</code></td><td>optional</td><td>Ops always allowed.</td></tr><tr><td><code>deny</code></td><td><code>op list</code></td><td>optional</td><td>Ops always refused — deny wins over allow.</td></tr><tr><td><code>deny_adhoc</code></td><td><code>bool</code></td><td>optional</td><td>Refuse <code>-s VAR=cuora://ref</code> ad-hoc injection on <code>run</code>/<code>env</code> (MED-5). Without it, a posture like <code>deny = [&quot;get&quot;]</code> is sidestepped: <code>cuora run -s V=cuora://x -- printenv V</code> <em>is</em> a get. Declared <code>[secrets]</code> injection is unaffected — the declared surface is auditable config, not an ad-hoc grab.</td></tr></tbody></table><h2 id="serve-—-the-cuora-serve-surface" tabindex="-1"><code>[serve]</code> — the <code>cuora serve</code> surface <a class="header-anchor" href="#serve-—-the-cuora-serve-surface" aria-label="Permalink to &quot;`[serve]` — the `cuora serve` surface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>field</th><th>type</th><th>required</th><th>notes</th></tr></thead><tbody><tr><td><code>pdp</code></td><td><code>table</code></td><td>optional</td><td>The external policy decision point serve consults before every op that can materialize (<code>get</code>/<code>put</code>/<code>rm</code>/<code>rotate</code>/ <code>list</code>/<code>check</code>). Absent, no consult happens — the advisory posture only.</td></tr></tbody></table><h2 id="serve-pdp-—-the-external-policy-decision-point" tabindex="-1"><code>[serve.pdp]</code> — the external policy decision point <a class="header-anchor" href="#serve-pdp-—-the-external-policy-decision-point" aria-label="Permalink to &quot;`[serve.pdp]` — the external policy decision point&quot;">​</a></h2><table tabindex="0"><thead><tr><th>field</th><th>type</th><th>required</th><th>notes</th></tr></thead><tbody><tr><td><code>exec</code></td><td><code>string</code></td><td>required</td><td>The exec driver command — run via <code>sh -c</code> once per decision, request JSON on stdin, verdict JSON on stdout. <strong>Trust root</strong>: the line authorizes shell exec; the child inherits only the <code>cuora-shell</code> env allowlist. <code>cuora serve</code> warns when this arrives via an implicit <code>./cuora.toml</code> — pin config with <code>--config</code>/<code>$CUORA_CONFIG</code>.</td></tr><tr><td><code>allow_on_error</code></td><td><code>bool</code></td><td>optional</td><td>What an unreachable PDP means. <code>false</code> (default) fails <strong>closed</strong> — the op is denied; a policy engine that can&#39;t answer must not silently mean &quot;allowed&quot;. <code>true</code> fails open — the op runs anyway and the audit event records the degraded verdict.</td></tr><tr><td><code>timeout_ms</code></td><td><code>int</code></td><td>optional</td><td>Per-decision deadline in milliseconds — the child is killed and the consult counts as <em>unreachable</em> past it. A hung or flooding PDP must never freeze the serve loop; absent → 5000.</td></tr></tbody></table><h2 id="envs-route-forms" tabindex="-1"><code>[envs]</code> route forms <a class="header-anchor" href="#envs-route-forms" aria-label="Permalink to &quot;`[envs]` route forms&quot;">​</a></h2><p>Either a bare vault name or the table above:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">envs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dev = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;local&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prod = { vault = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cloud&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><ul><li><code>deny_unknown_fields</code>: typos in field names fail the load.</li><li>Search order: <code>--config</code> → <code>$CUORA_CONFIG</code> → <code>./cuora.toml</code> → <code>~/.config/cuora/cuora.toml</code>. The file is optional — no <code>cuora.toml</code> anywhere just means defaults (local age vault, <code>dev</code> env).</li><li>Token values never live in the file — <code>token_env</code> fields name the env var that carries them.</li><li><code>cuora schema</code> emits the JSON Schema for this shape; <code>cuora check</code> validates a real file end-to-end.</li></ul>',20)])])}const v=t(c,[["render",r]]);export{p as __pageData,v as default};
